.skills-panel {
  padding: 0;
}

.skills-panel__actions {
  display: flex;
  justify-content: flex-end;
  padding: 0 0 8px;
}

.skills-panel__create-btn {
  background: none;
  border: 1px solid var(--color-border-medium);
  cursor: pointer;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--color-text-muted);
  font-size: 18px;
  line-height: 1;
  transition: background 0.15s, color 0.15s;
}

.skills-panel__create-btn:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.skills-panel__empty {
  font-size: 13px;
  color: var(--color-text-faint);
  padding: 0;
  margin: 0;
}

.skills-panel__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.skills-panel__item {
  margin-bottom: 8px;
  padding: 8px;
  border-radius: 6px;
  border: 1px solid var(--color-border-light);
  cursor: pointer;
}

.skills-panel__item:hover {
  border-color: var(--color-border-medium);
}

.skills-panel__item-header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.skills-panel__name {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-primary);
  padding: 0;
  text-align: left;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-panel__loading {
  font-size: 12px;
  color: var(--color-text-muted);
}

.skills-panel__use-btn {
  background: var(--color-accent-primary);
  color: #fff;
  border: none;
  border-radius: 4px;
  font-size: 11px;
  padding: 2px 8px;
  cursor: pointer;
  white-space: nowrap;
}

.skills-panel__use-btn:hover {
  background: var(--color-accent-primary-hover);
}

.skills-panel__delete-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 16px;
  color: var(--color-text-muted);
  padding: 0 2px;
  opacity: 1;
}

.skills-panel__delete-btn:hover {
  color: var(--color-error);
}

.skills-panel__desc {
  font-size: 12px;
  color: var(--color-text-muted);
  margin: 4px 0 0;
  line-height: 1.4;
}

.skills-panel__item--disabled {
  opacity: 0.5;
}

.skills-panel__toggle-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-muted);
  padding: 0 2px;
  line-height: 1;
  display: flex;
  align-items: center;
  transition: color 0.15s;
}

.skills-panel__toggle-btn:hover {
  color: var(--color-text-primary);
}

.skills-panel__desc--truncated {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

